        <label for="bulk-grade-from">From</label>
        <input #bulkGradeFrom id="bulk-grade-from" type="date" data-testid="bulk-grade-from"
          (input)="bulkGradeError.set('')" />
        <button type="button" data-testid="bulk-grade-apply"
          (click)="gradeSelected(bulkGrade.value, bulkGradeFrom.value)">Grade selected people</button>
        @if (bulkGraded() !== null) {
          <p role="status">Changed <strong data-testid="bulk-graded">{{ bulkGraded() }}</strong></p>
        }
        @if (bulkGradeError()) {
          <p role="alert" data-testid="person-error">{{ bulkGradeError() }}</p>
        }
      </div>
      <button type="button" data-testid="export-people" (click)="exportCsv()">Export people (CSV)</button>
      <table data-testid="people">
        <thead>
          <tr><th scope="col"><span class="visually-hidden">Select</span></th><th scope="col">Name</th><th scope="col">Grade</th><th scope="col">Active</th><th scope="col">Terms</th><th scope="col">Contact</th><th scope="col">Aliases</th><th scope="col">Clashing</th><th scope="col">Claimed</th><th scope="col">Due</th><th scope="col">Settled due</th><th scope="col">Open due</th>@for (pd of periods(); track pd.id) {<th scope="col">Due in {{ pd.name }}</th>}<th scope="col">Excess</th><th scope="col">Cut total</th><th scope="col">Statements</th><th scope="col">Last stated</th><th scope="col">Stated on</th><th scope="col">Retired</th><th scope="col">Retired from</th><th scope="col">On hold</th><th scope="col">Overdue</th><th scope="col">Overdue due</th><th scope="col">Due aged 0–30 days</th><th scope="col">Due aged 31–60 days</th><th scope="col">Due aged 61+ days</th><th scope="col">Patrons</th><th scope="col">Backing</th><th scope="col">Watched</th><th scope="col">Claims</th><th scope="col"><span class="visually-hidden">Actions</span></th></tr>
        </thead>
        <tbody>
          @for (p of shown(); track p.id) {
            <tr [attr.data-testid]="'person-row-' + p.id">
              <td>
                <input type="checkbox" data-testid="person-select" [checked]="selectedPeople().has(p.id)"
                  (change)="selectPerson(p.id, $any($event.target).checked)"
                  [attr.aria-label]="'Select ' + p.name" />
              </td>
              <td data-testid="person-name">{{ p.name }}</td>
              <td data-testid="person-grade">{{ gradeOf(p) }}</td>
              <td data-testid="person-active">{{ activeOf(p) ? 'yes' : 'no' }}</td>
              <td data-testid="person-terms">{{ p.terms ?? '' }}</td>
              <td data-testid="person-contact">{{ p.contact ?? '' }}</td>
              <td data-testid="person-aliases">{{ p.aliases.join(', ') }}</td>
              <td data-testid="person-clashing">{{ p.clashing ? 'yes' : 'no' }}</td>
              <td data-testid="person-claimed">{{ claimed().get(p.id) ?? '0.00' }}</td>
              <td data-testid="person-due-total">{{ dueOf(p) ?? 'n/a' }}</td>
              <td data-testid="person-settled-total">{{ settledTotalOf(p) }}</td>
